import React from 'react';
import { render, screen } from '@testing-library/react';
import Paragraph from './Paragraph';

describe('Paragraph', () => {
  test('should render without crashing', () => {
    const { container } = render(<Paragraph>Paragraph</Paragraph>);
    expect(screen.getByText('Paragraph')).toBeInTheDocument();
    expect(container.querySelector('p')).not.toBeNull();
  });
  test('should render as a paragraph', () => {
    const { container } = render(
      <Paragraph size="basis" colortype="secondary" foreground="true">
        Paragraph
      </Paragraph>
    );
    expect(screen.getByText('Paragraph')).toBeInTheDocument();
    expect(container.querySelector('p')).not.toBeNull();
  });
  test('should render as a paragraph', () => {
    const { container } = render(
      <Paragraph size="xsmall" colortype="error">
        Paragraph
      </Paragraph>
    );
    expect(screen.getByText('Paragraph')).toBeInTheDocument();
    expect(container.querySelector('p')).not.toBeNull();
  });
  test('should render as a paragraph', () => {
    const { container } = render(
      <Paragraph size="small" colortype="success">
        Paragraph
      </Paragraph>
    );
    expect(screen.getByText('Paragraph')).toBeInTheDocument();
    expect(container.querySelector('p')).not.toBeNull();
  });
});
